package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.EmploymentContract; import EmployeeManagementSystem.repository.EmploymentContractRepository;
import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service public class EmploymentContractServiceImpl implements EmploymentContractService{
 private final EmploymentContractRepository repo; public EmploymentContractServiceImpl(EmploymentContractRepository r){repo=r;}
 public List<EmploymentContract> my(String u){return repo.findByUserIdOrderByStartDateDesc(u);} public List<EmploymentContract> all(){return repo.findAllByOrderByStartDateDesc();}
 private void validate(EmploymentContract x){if(x.getContractType()==null||x.getContractType().isBlank())throw new IllegalArgumentException("Contract type is required.");if(x.getStartDate()==null)throw new IllegalArgumentException("Start date is required.");if(x.getEndDate()!=null&&x.getEndDate().isBefore(x.getStartDate()))throw new IllegalArgumentException("End date cannot be before start date.");if(x.getNoticeDays()!=null&&x.getNoticeDays()<0)throw new IllegalArgumentException("Notice days cannot be negative.");}
 public EmploymentContract create(EmploymentContract x,String u,String n){validate(x);if(repo.existsByUserIdAndContractTypeAndStatusIn(u,x.getContractType(),List.of("ACTIVE","RENEWAL_PENDING")))throw new IllegalArgumentException("An active contract of this type already exists.");x.setId(null);x.setUserId(u);x.setEmployeeName(n);x.setStatus("ACTIVE");return repo.save(x);}
 public EmploymentContract update(Long id,EmploymentContract x,String u,boolean mgmt){EmploymentContract e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Contract not found."));if(!mgmt&&!u.equals(e.getUserId()))throw new SecurityException("You can only manage your own contracts.");validate(x);e.setContractType(x.getContractType());e.setDesignation(x.getDesignation());e.setDepartmentName(x.getDepartmentName());e.setStartDate(x.getStartDate());e.setEndDate(x.getEndDate());e.setNoticeDays(x.getNoticeDays());e.setWorkMode(x.getWorkMode());e.setEmploymentStatus(x.getEmploymentStatus());e.setDocumentReference(x.getDocumentReference());e.setRenewalComment(x.getRenewalComment());if(!mgmt)e.setStatus("REVIEW_REQUIRED");return repo.save(e);}
 public void delete(Long id,String u,boolean mgmt){EmploymentContract e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Contract not found."));if(!mgmt&&!u.equals(e.getUserId()))throw new SecurityException("Access denied.");repo.delete(e);}
 public EmploymentContract review(Long id,String status,String comment,String reviewer){EmploymentContract e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Contract not found."));if(!Set.of("ACTIVE","RENEWAL_PENDING","EXPIRED","TERMINATED").contains(status))throw new IllegalArgumentException("Invalid contract status.");e.setStatus(status);e.setReviewerUserId(reviewer);e.setReviewerComment(comment);e.setReviewedAt(LocalDateTime.now());return repo.save(e);}
}
